  <script>
    const formatNumber = (num) => num.toLocaleString('en-US');

    const stats = document.querySelectorAll('.stat-value');
    let statsAnimated = false;
    const animateCounter = (el, target, duration = 1500, delay = 0) => {
      const startTime = performance.now() + delay;
      const step = (now) => {
        if (now < startTime) return requestAnimationFrame(step);
        const p = Math.min((now - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - p, 3);
        el.textContent = formatNumber(Math.floor(target * eased));
        if (p < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    };

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting && !statsAnimated) {
          statsAnimated = true;
          stats.forEach((el, idx) => animateCounter(el, Number(el.dataset.target), 1400, idx * 180));
          statsObserver.disconnect();
        }
      });
    }, { threshold: 0.4 });
    const statsSection = document.getElementById('stats');
    if (statsSection) statsObserver.observe(statsSection);

    const tabs = document.querySelectorAll('.tab');
    const panels = document.querySelectorAll('.search-panel');
    tabs.forEach((tab) => {
      tab.addEventListener('click', () => {
        tabs.forEach((t) => { t.classList.remove('active'); t.setAttribute('aria-selected', 'false'); });
        panels.forEach((p) => p.classList.remove('active'));
        tab.classList.add('active');
        tab.setAttribute('aria-selected', 'true');
        const panel = document.querySelector(`[data-panel="${tab.dataset.tab}"]`);
        if (panel) panel.classList.add('active');
      });
    });

    const filters = document.querySelectorAll('.filter');
    const screenGrid = document.getElementById('screenGrid');
    const screenData = {
      "Profile": ["Profile", "Activity", "Settings", "Security", "Edit", "Avatar", "Stats", "Preferences"],
      "Wallet": ["Balance", "Cards", "Transfer", "History", "Send", "Receive", "Crypto", "Limits"],
      "Welcome": ["Intro", "Benefits", "Tutorial", "Get Started", "Permissions", "Tips", "Signup", "Success"],
      "Account Setup": ["Create", "Email", "Verify", "Password", "Username", "Avatar", "Sync", "Complete"],
      "Home": ["Feed", "Trending", "Quick Actions", "Modules", "Shortcuts", "Stories", "Explore", "Updates"],
      "Subscription & Paywall": ["Plans", "Trial", "Upgrade", "Benefits", "Billing", "Discount", "Annual", "Confirm"],
      "Login": ["Email", "Password", "SSO", "Magic Link", "2FA", "Reset", "Welcome Back", "Success"],
      "Settings": ["Preferences", "Notifications", "Privacy", "Theme", "Language", "Account", "Support", "Danger Zone"],
      "Checkout": ["Cart", "Address", "Shipping", "Payment", "Review", "Coupon", "Confirm", "Receipt"],
      "Collections": ["Board", "Saved", "Tags", "Folders", "Share", "Collaborate", "Archive", "Pin"]
    };

    function renderScreens(category) {
      if (!screenGrid) return;
      screenGrid.innerHTML = '';
      (screenData[category] || []).forEach((item) => {
        const card = document.createElement('div');
        card.className = 'screen';
        card.dataset.label = item;
        screenGrid.appendChild(card);
      });
    }

    filters.forEach((f) => {
      f.addEventListener('click', () => {
        filters.forEach((x) => x.classList.remove('active'));
        f.classList.add('active');
        renderScreens(f.dataset.filter);
      });
    });
    renderScreens('Profile');

    const modeBtns = document.querySelectorAll('.toggle button');
    const modePanels = document.querySelectorAll('.mode-panel');
    modeBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        modeBtns.forEach((b) => { b.classList.remove('active'); b.setAttribute('aria-selected', 'false'); });
        modePanels.forEach((p) => p.classList.remove('active'));
        btn.classList.add('active');
        btn.setAttribute('aria-selected', 'true');
        const panel = document.querySelector(`[data-mode-panel="${btn.dataset.mode}"]`);
        if (panel) panel.classList.add('active');
      });
    });
  </script>
